import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type WriteOnAnimationProps = Record<string, any>;

const WriteOnAnimation: React.FC<WriteOnAnimationProps> = ({
  backgroundColor = "#06170e",
  transparentBackground = false,
  durationInSeconds = 6,
  primaryStat = "100 Million Hectares",
  descriptionText = "of land under restoration",
  primaryColor = "#4ade80",
  textColor = "#f8fafc",
  cursorColor = "#4ade80",
  typingSpeedMultiplier = 1,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Montserrat"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Base layout calculations
  const safeAreaX = width * 0.1;
  const mainFontSize = width * 0.06;
  const subFontSize = width * 0.035;

  // Animation Timings
  const startDelayFrames = 15;
  const baseFramesPerChar = 1.2 / typingSpeedMultiplier;
  
  // Primary Text Timing
  const primaryTextDuration = Math.max(1, primaryStat.length * baseFramesPerChar);
  const primaryTextEnd = startDelayFrames + primaryTextDuration;
  
  // Pause between lines
  const interLinePause = fps * 0.5;
  const subTextStart = primaryTextEnd + interLinePause;
  
  // Description Text Timing
  const subTextDuration = Math.max(1, descriptionText.length * baseFramesPerChar);
  const subTextEnd = subTextStart + subTextDuration;

  // Calculate visible characters based on frame
  const visiblePrimaryChars = Math.floor(
    interpolate(frame, [startDelayFrames, primaryTextEnd], [0, primaryStat.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const visibleSubChars = Math.floor(
    interpolate(frame, [subTextStart, subTextEnd], [0, descriptionText.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const displayedPrimaryText = primaryStat.substring(0, visiblePrimaryChars);
  const displayedSubText = descriptionText.substring(0, visibleSubChars);

  // Cursor Logic
  const isTypingPrimary = frame >= startDelayFrames && frame < primaryTextEnd;
  const isTypingSub = frame >= subTextStart && frame < subTextEnd;
  const isTyping = isTypingPrimary || isTypingSub;
  
  // Blink cursor when not actively typing (every ~0.5 seconds)
  const cursorBlink = Math.floor(frame / (fps / 2)) % 2 === 0;
  const cursorOpacity = isTyping ? 1 : (cursorBlink ? 1 : 0);

  // Entrance spring for the whole container to give it a polished feel
  const containerScale = spring({
    frame,
    fps,
    config: { damping: 20, mass: 0.8 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          width: "100%",
          height: "100%",
          paddingLeft: safeAreaX,
          paddingRight: safeAreaX,
          transform: `scale(${containerScale})`,
          transition: "none",
        }}
      >
        <div 
          style={{ 
            display: "flex", 
            flexDirection: "column",
            gap: height * 0.02,
            transition: "none",
          }}
        >
          {/* Primary Stat Line */}
          <div style={{ display: "flex", alignItems: "center", transition: "none", height: mainFontSize * 1.2 }}>
            <span
              style={{
                fontFamily: "Montserrat",
                fontWeight: 800,
                fontSize: mainFontSize,
                color: primaryColor,
                lineHeight: 1,
                transition: "none",
                letterSpacing: "-0.02em",
              }}
            >
              {displayedPrimaryText}
            </span>
            {/* Show cursor on first line only before second line starts typing */}
            {frame < subTextStart && (
              <span
                style={{
                  display: "inline-block",
                  width: width * 0.015,
                  height: mainFontSize * 0.9,
                  backgroundColor: cursorColor,
                  marginLeft: width * 0.008,
                  opacity: cursorOpacity,
                  transition: "none",
                }}
              />
            )}
          </div>

          {/* Description Line */}
          <div style={{ display: "flex", alignItems: "center", transition: "none", height: subFontSize * 1.2 }}>
            <span
              style={{
                fontFamily: "Montserrat",
                fontWeight: 500,
                fontSize: subFontSize,
                color: textColor,
                lineHeight: 1,
                transition: "none",
                letterSpacing: "0.01em",
              }}
            >
              {displayedSubText}
            </span>
            {/* Show cursor on second line once it starts */}
            {frame >= subTextStart && (
              <span
                style={{
                  display: "inline-block",
                  width: width * 0.01,
                  height: subFontSize * 0.9,
                  backgroundColor: cursorColor,
                  marginLeft: width * 0.008,
                  opacity: cursorOpacity,
                  transition: "none",
                }}
              />
            )}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WriteOnAnimation;